import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%91%E3%82%BD%E3%82%B3%E3%83%B3%E3%81%8C%E6%AC%B2%E3%81%97%E3%81%8F%E3%81%AA%E3%82%8B%E4%BD%9C%E6%A5%AD.html","title":"パソコンが欲しくなる作業","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.65,"words":196},"filePathRelative":"パソコンが欲しくなる作業.md"}`),a={name:`パソコンが欲しくなる作業.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="パソコンが欲しくなる作業" tabindex="-1"><a class="header-anchor" href="#パソコンが欲しくなる作業"><span>パソコンが欲しくなる作業</span></a></h1><p><a href="./Rhinocs.html">Rhinocs</a>が大分実用になり、お出掛けにBOOXと折り畳みキーボードという態勢になってくると、 逆にPCが欲しくなる瞬間というのに直面するようになる。 どういう時にパソコンが欲しくなるだろうか？</p><p>たとえば、<a href="./【書籍】原論文から解き明かす生成AI.html">【書籍】原論文から解き明かす生成AI</a>を読んでいて、 そこから論文が参照されている時などはPCが欲しくなった。 ググったりしつつpdfを眺めていくような作業、及びそれらへのメモを残していくような作業はPC向きだ。</p><p>一方で集中して論文を読むなら、PCよりもBOOXなどの方がいいだろうから、 たくさんの論文を散漫的に読みたい時がPC向きと言える気がする。</p><p>この他、ググってそのリンクを貼りつつ何かを書いて行きたい時にPCが欲しくなる。</p><p>あとは、まさにこの文章を打っているエディタやSKKにバグを見つけた時などもPCが欲しくなる。 その場で直すのはPCでやりたい作業だ。</p><p>あとは他のWikiNameのリンクを貼りたい時で、WikiNameが調べないと分からない時もPCが欲しくなる。 これはWikiNameの一覧を絞り込みで探せればBOOXでも問題なくなる気がする。</p><p>他にはSNSに何かつぶやきたい時、というのもあるが、これはだいたいロクでもない事に気が散る時なので、 むしろやりにくくて良い、という気もするな。</p><p>最近出番は無いが、講義動画を見る時もPCが欲しいと思うな。 こういう動画をみながらメモを書く、とかのように、 二つの事を同時にやりたい時はPC向きなんだよな。</p><p>逆にPCが欲しくならない事として、文章を書く、というのがある。 むしろ文章を書くには、BOOX+キーボードの方が集中出来て良い。 じっくり考えて何かを書くにはPCはかえっていまいちだよな。 読んでいる本のメモなどを書くにはPCは良いけれど。 エディタからブラウザへの切り替えコストが高い方が、じっくり考えるのには向いている気がする。</p><p>最近小さなブログ記事が増えたのは、この文章作成環境の変化はある気がするな。</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};